window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["reflection"]={"title":"反思与自我修正：让失败证据改变下一次行动","subtitle":"区分空泛自评、外部反馈和可验证修正，用最小改动、停止条件与版本化经验避免“再想一遍”制造更自信的错误。","thesis":"反思不是让模型多写一段自我批评，而是把<b>外部失败证据</b>压缩成可证伪原因假设和单一修改，再用同一验收标准复测；没有新证据的循环只是在同一盲点内重新采样。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"v1 单键、跨用户反例","rule":"只改 key 为 (user_id,product_id)","steps":"v2 两组均 2/2","interpretation":"只有复合键满足完整目标"}}],"formulas":[],"termReviews":[{"section":4,"reviewedAt":"2026-07-27","terms":[{"name":"保护性回归","meaning":"防止修复一个缺陷时破坏原本正确行为的测试集合","purpose":"同时验证缓存隔离与原有命中收益","definitionEvidence":"保护性回归未破坏","purposeEvidence":"隔离测试和命中保护测试"},{"name":"TTL","meaning":"缓存项目在被视为过期前允许存活的时间","purpose":"区分键隔离错误与缓存生命周期配置错误","definitionEvidence":"不改测试与 TTL","purposeEvidence":"复合键补丁"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"反思修正用外部失败证据约束原因假设和最小补丁。","evidence":"输出可证伪原因假设、最小补丁及复测决定"},"problem":{"answer":"它解决同一模型再想一遍为何不必然纠错。","evidence":"没有新证据的再想一遍"},"inputOutput":{"answer":"输入候选证据验收预算，输出假设补丁复测。","evidence":"输入候选、外部失败证据、受保护验收和修改预算"},"mechanism":{"answer":"由测试检索环境等证据改变状态，再提出可证伪修改。","evidence":"真正改变信息状态"},"interpretation":{"answer":"成功必须修复原失败且保护性回归没有破坏。","evidence":"保护性回归未破坏"},"boundary":{"answer":"无新证据循环只是同一盲点中的重新采样。","evidence":"同一盲点内重采样"}},{"section":2,"definition":{"answer":"反思闭环分离生成验证诊断修改和复测角色产物。","evidence":"输出保留、回退、继续调查或停止"},"problem":{"answer":"它解决为何生成评判诊断修改必须保持不同接口。","evidence":"产物与接口分开"},"inputOutput":{"answer":"输入候选验证假设补丁验收，输出闭环动作。","evidence":"输入候选、验证结果、原因假设、补丁和同一验收"},"mechanism":{"answer":"执行器生成验证器举证反思器假设再应用复测。","evidence":"执行器生成，验证器只给可复现证据"},"interpretation":{"answer":"同一模型可分时扮演角色但状态与标准必须隔离。","evidence":"角色可以由同一模型分时承担"},"boundary":{"answer":"评判者不能通过降低验收标准伪造修复。","evidence":"不得偷偷降低验收标准"}},{"section":3,"definition":{"answer":"反思记录是能把失败证据转成单一可验收动作的结构。","evidence":"输出可执行且可审计的修正计划"},"problem":{"answer":"它解决检查代码逻辑这类空泛批评为何无效。","evidence":"不能驱动验收"},"inputOutput":{"answer":"输入失败版本假设动作验证，输出可审计计划。","evidence":"输入失败现象、环境版本、原因假设、单一动作和预期验证"},"mechanism":{"answer":"记录证据机制补丁和失败保护双测试。","evidence":"缓存串值证据、缺 user_id 的可证伪机制"},"interpretation":{"answer":"原因不明先做区分实验，不一次列十种猜测。","evidence":"原因不明时先做区分实验"},"boundary":{"answer":"无定位动作的泛泛建议不能作为修正记录。","evidence":"“检查代码逻辑”没有定位动作"}},{"section":4,"definition":{"answer":"缓存案例把跨用户反例转成复合键最小修复。","evidence":"输出 v2 复合键或回退"},"problem":{"answer":"它解决怎样证明第二次修复来自反馈而不是走运。","evidence":"证明修复受反馈约束"},"inputOutput":{"answer":"输入单键反例双测试，输出复合键或回退。","evidence":"输入 v1 单键、跨用户反例、隔离测试和命中保护测试"},"mechanism":{"answer":"只改复合键并复跑失败测试与保护性测试。","evidence":"只改 key 为 (user_id,product_id)"},"interpretation":{"answer":"复合键两组全过，禁缓存则破坏命中契约。","evidence":"v2 两组均 2/2"},"boundary":{"answer":"只看失败用例会错误接受禁用缓存的过度修复。","evidence":"禁用缓存虽修隔离却破坏命中"}},{"section":5,"definition":{"answer":"最小修改控制每轮改动范围以保留因果归因和回退。","evidence":"输出一个可回退补丁序列及归因证据"},"problem":{"answer":"它解决一次改五处即使通过也为何不利于学习。","evidence":"先改能区分假设的最小范围"},"inputOutput":{"answer":"输入假设 diff 依赖测试验收，输出补丁序列。","evidence":"输入当前原因假设、代码 diff、相互依赖、失败测试和保护验收"},"mechanism":{"answer":"应用最小区分补丁，失败回退，依赖修改分检查点。","evidence":"多项依赖可用检查点分步"},"interpretation":{"answer":"通过结果才能归因到受控修改而非五项混合。","evidence":"只能把收益归因到这一组受控修改"},"boundary":{"answer":"不得删测试吞异常放宽断言来制造绿色。","evidence":"不得删除测试、吞异常或放宽断言"}},{"section":6,"definition":{"answer":"反思记忆保存带条件版本反例和过期规则的验证经验。","evidence":"输出可检索但需重新核对前提的经验"},"problem":{"answer":"它解决完整失败对话长期保存为何会污染新任务。","evidence":"不能把过去结论当当前事实"},"inputOutput":{"answer":"输入失败条件信号策略反例版本，输出条件经验。","evidence":"输入已验证失败模式、适用条件、诊断信号、策略、反例、来源版本和过期规则"},"mechanism":{"answer":"把局部验证结果抽象为带前提经验并在新任务复核。","evidence":"多租户缓存键覆盖租户边界"},"interpretation":{"answer":"适用条件满足才允许迁移经验到新任务。","evidence":"需重新核对前提"},"boundary":{"answer":"两个同源模型角色不能替代独立证据和人工。","evidence":"不能替代事实来源、测试或合格人工"}},{"section":7,"definition":{"answer":"停止策略用边际修好改坏成本新证据决定反思轮数。","evidence":"输出继续、回退、报告未知或人工升级"},"problem":{"answer":"它解决修正轮数增加时何时边际收益转负。","evidence":"边际收益和改坏风险怎样共同决定停止"},"inputOutput":{"answer":"输入每轮收益损害成本证据稳定性，输出停止动作。","evidence":"输入每轮修好数、改坏数、成本延迟、新证据和验证器稳定性"},"mechanism":{"answer":"逐轮计算净收益并检查无证据循环验收冲突预算。","evidence":"净收益依次为 31、4、−4"},"interpretation":{"answer":"第三轮负四表示默认继续会比停止更差。","evidence":"第三轮不应默认执行"},"boundary":{"answer":"轮数更多不等于修正更可靠，耗尽应明确升级。","evidence":"轮数更多不代表修正更可靠"}},{"section":8,"definition":{"answer":"反思评测在同预算下隔离外部反馈相对多采样的贡献。","evidence":"输出最终成功、首轮正确改坏率、边际收益、轮数、回退和升级"},"problem":{"answer":"它解决多调用本身提高命中时如何证明反馈有用。","evidence":"若无反馈多采样同样有效"},"inputOutput":{"answer":"输入四种同预算策略，输出成功损害与成本指标。","evidence":"输入同预算的直接单次、无反馈多采样、外部反馈反思和更强模型单次"},"mechanism":{"answer":"用隐藏测试和原正确对照比较反馈策略与无反馈策略。","evidence":"隐藏测试防止针对可见验收过拟合"},"interpretation":{"answer":"必须同时报告改好和改坏而非只看最终成功。","evidence":"首轮正确改坏率"},"boundary":{"answer":"无反馈同效时不能声称复杂反思框架必要。","evidence":"没有证明复杂反思框架的必要性"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分反馈与自评；写出可执行反思记录；控制修正范围和停止条件；评估改好率与改坏率。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>“再想一遍”为什么不等于纠错<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">同一个模型读同一份上下文，凭什么第二遍一定比第一遍正确？</p><p>模型可以发现表面矛盾，也可能重复原假设、迎合“请找错误”的指令，甚至把原本正确的答案改坏。真正改变信息状态的是测试失败、编译器诊断、检索来源、环境观察或人类规则判断。反思器的任务是解释这些证据如何否定当前候选，而不是生成更长的内心独白。</p><div class=\"dd-note\"><b>操作定义：</b>一次修正只有在“候选发生可定位变化，并通过此前失败的验收且未破坏保护性回归”时才算成功。</div><p>反思修正输入候选、外部失败证据、受保护验收和修改预算，输出可证伪原因假设、最小补丁及复测决定。测试编译检索环境或人工规则真正改变信息状态，模型自我批评本身不会；成功要求原失败消失且保护性回归未破坏。没有新证据的再想一遍只是同一盲点内重采样。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>反思闭环有哪些角色<span class=\"dd-badge eng\">机制</span></h2><p class=\"dd-lead\">生成、评判、诊断和修改为什么要保留不同产物？</p><p>执行器产生候选；验证器只返回可复现的通过/失败证据；反思器提出原因假设和最小修改；执行器应用补丁；同一验证器复测。角色可以由同一模型分时承担，但状态与接口必须分开，避免评判器偷偷降低标准，或修改器把未经验证的解释当事实。</p><div class=\"dd-chain\">候选 → 外部验证 → 失败证据 → 原因假设 → 单一补丁 → 原测试 + 回归测试 → 保留或回退</div><p>反思闭环输入候选、验证结果、原因假设、补丁和同一验收，输出保留、回退、继续调查或停止。执行器生成，验证器只给可复现证据，反思器提出假设与单一改动，执行器应用后原验证器复测；产物与接口分开。评判者不得偷偷降低验收标准。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>一条反思记录必须能驱动动作<span class=\"dd-badge eng\">记录</span></h2><p class=\"dd-lead\">“检查代码逻辑”为什么是一条无效反思？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>字段</th><th>缓存隔离案例</th><th>验收作用</th></tr></thead><tbody><tr><td>失败证据</td><td>用户 B 读取相同 product_id 时命中用户 A 的价格</td><td>可复现，不依赖语气判断</td></tr><tr><td>原因假设</td><td>缓存键只有 product_id，缺 user_id</td><td>指出可证伪机制</td></tr><tr><td>单一改动</td><td>键改为 (user_id, product_id)</td><td>限制归因范围</td></tr><tr><td>预期验证</td><td>跨用户不命中；同用户重复请求仍命中</td><td>同时保护隔离与缓存收益</td></tr></tbody></table></div><p>高质量记录既不能只复述错误，也不能一次列十个可能原因。若原因仍不确定，应先设计区分性实验，例如记录实际 key 或构造两个用户同商品的成对测试，再决定改哪里。</p><p>反思记录输入失败现象、环境版本、原因假设、单一动作和预期验证，输出可执行且可审计的修正计划。记录必须指出缓存串值证据、缺 user_id 的可证伪机制、复合键补丁和隔离/命中双测试；原因不明时先做区分实验。“检查代码逻辑”没有定位动作，不能驱动验收。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>一次失败怎样变成最小修正<span class=\"dd-badge math\">运行示例</span></h2><p class=\"dd-lead\">怎样证明修复来自反馈，而不是恰好第二次生成走运？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 680 235\" role=\"img\" aria-label=\"缓存隔离缺陷从测试失败到最小补丁和回归验证的反思闭环\"><defs><marker id=\"rf1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"16\" y=\"48\" width=\"122\" height=\"90\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"77\" y=\"72\" text-anchor=\"middle\" class=\"svg-t\">候选 v1</text><text x=\"77\" y=\"94\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">key = product_id</text><text x=\"77\" y=\"115\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">单用户测试通过</text><path d=\"M138,93 L184,93\" stroke=\"#6b7484\" marker-end=\"url(#rf1)\"/><rect x=\"186\" y=\"34\" width=\"134\" height=\"118\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"253\" y=\"58\" text-anchor=\"middle\" class=\"svg-t\">外部反例</text><text x=\"253\" y=\"81\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">A 写入商品 42</text><text x=\"253\" y=\"100\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">B 读取商品 42</text><text x=\"253\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">实际得到 A 的值</text><text x=\"253\" y=\"138\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">期望：B 独立查询</text><path d=\"M320,93 L366,93\" stroke=\"#6b7484\" marker-end=\"url(#rf1)\"/><rect x=\"368\" y=\"34\" width=\"134\" height=\"118\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"435\" y=\"58\" text-anchor=\"middle\" class=\"svg-t\">反思记录</text><text x=\"435\" y=\"81\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">证据：跨用户串值</text><text x=\"435\" y=\"100\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">假设：key 缺 user</text><text x=\"435\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">改动：复合键</text><text x=\"435\" y=\"138\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">不改测试与 TTL</text><path d=\"M502,93 L548,93\" stroke=\"#6b7484\" marker-end=\"url(#rf1)\"/><rect x=\"550\" y=\"48\" width=\"114\" height=\"90\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"607\" y=\"72\" text-anchor=\"middle\" class=\"svg-t\">候选 v2</text><text x=\"607\" y=\"94\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">隔离测试通过</text><text x=\"607\" y=\"113\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">命中测试也通过</text><path d=\"M607,139 C602,208 253,211 253,154\" fill=\"none\" stroke=\"#6b7484\" marker-end=\"url(#rf1)\"/><text x=\"430\" y=\"205\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">若仍失败，只携带新证据进入下一轮；两轮无新信息则停止并升级</text></svg><figcaption>图 1　反思的因果价值来自外部反例约束了原因与补丁；复测同时包含失败测试和保护性测试，防止“修好隔离但取消缓存”。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>轮次</th><th>隔离测试</th><th>同用户命中测试</th><th>结论</th></tr></thead><tbody><tr><td>v1</td><td>0/2 通过</td><td>2/2 通过</td><td>有缓存但越权串值</td></tr><tr><td>v2 复合键</td><td>2/2 通过</td><td>2/2 通过</td><td>保留</td></tr><tr><td>备选“禁用缓存”</td><td>2/2 通过</td><td>0/2 通过</td><td>修症状但破坏性能契约</td></tr></tbody></table></div><p>若只看失败用例，复合键和禁用缓存都得到 100% 通过；加入保护性测试后，只有复合键满足完整目标。这说明反思质量受验收覆盖上限约束，不能靠批评措辞弥补缺失测试。</p><p>缓存案例输入 v1 单键、跨用户反例、隔离测试和命中保护测试，输出 v2 复合键或回退。规则是只改 key 为 (user_id,product_id)，复跑失败测试与保护测试；v2 两组均 2/2，通过，而禁用缓存虽修隔离却破坏命中。只有复合键满足完整目标，证明修复受反馈约束。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>怎样控制修改范围与归因<span class=\"dd-badge eng\">最小改动</span></h2><p class=\"dd-lead\">为什么一次改五处即使测试通过也不利于学习？</p><p>同时更换键、TTL、序列化和数据库查询后，无法知道哪一项修复了缺陷，也无法定位新回归。反思循环应先应用能区分当前原因假设的最小补丁，记录 diff 和验证结果；若失败则回退并保留证据。对相互依赖的改动，可拆成有检查点的序列，而不是要求绝对“一行修复”。</p><p>验证标准应在循环外受保护。模型不得删除失败测试、放宽断言或把异常吞掉来制造绿色结果；需要修改测试时，必须由独立需求证据证明原验收错误。</p><p>最小修改输入当前原因假设、代码 diff、相互依赖、失败测试和保护验收，输出一个可回退补丁序列及归因证据。先改能区分假设的最小范围，失败则回退并保留结果；多项依赖可用检查点分步。测试通过后只能把收益归因到这一组受控修改。不得删除测试、吞异常或放宽断言制造绿色结果。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>反思记忆保存什么<span class=\"dd-badge intuition\">记忆</span></h2><p class=\"dd-lead\">把完整失败对话存入长期记忆，为什么容易污染下一次任务？</p><p>可复用经验应写成“适用条件—失败模式—诊断信号—已验证策略—反例/失效条件”，并带来源、版本和过期规则。例如“多租户缓存键必须覆盖租户边界”可迁移；“所有缓存都加 user_id”则会误伤公共数据。新任务检索到经验后仍要检查前提，不能把过去结论当当前事实。</p><div class=\"dd-note warn\"><b>同源偏差：</b>生成器和反思器即使使用两个调用，也可能共享训练偏差。事实任务优先引入来源，代码任务优先运行测试，高风险判断引入独立规则或合格人工，而不是仅换一个“审稿人”角色提示。</div><p>反思记忆输入已验证失败模式、适用条件、诊断信号、策略、反例、来源版本和过期规则，输出可检索但需重新核对前提的经验。把“多租户缓存键覆盖租户边界”保留为条件经验，而不是推广“所有缓存加 user_id”。同源模型角色不能替代事实来源、测试或合格人工。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>什么时候停止而不是继续反思<span class=\"dd-badge math\">预算</span></h2><p class=\"dd-lead\">修正轮数增加时，边际收益和改坏风险怎样共同决定停止？</p><p>假设 100 个首轮失败案例中，第 1 轮修好 35 个、改坏原本正确结果 4 个，净收益 31；第 2 轮再修好 10 个、改坏 6 个，净收益 4；第 3 轮修好 3 个、改坏 7 个，净收益 −4。总体成功率可能仍上升，但第三轮已不值得默认执行。应按任务切片报告每轮边际修复率、改坏率、成本与延迟。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>停止信号</th><th>动作</th></tr></thead><tbody><tr><td>连续两轮无新失败证据</td><td>停止，避免同一信息重采样</td></tr><tr><td>同一测试在两个补丁间来回</td><td>回到需求/状态建模，寻找共同约束</td></tr><tr><td>验证器不稳定或互相冲突</td><td>先修验收，不继续修改候选</td></tr><tr><td>达到成本、时间或风险上限</td><td>返回已知/未知并升级人工</td></tr></tbody></table></div><p>停止策略输入每轮修好数、改坏数、成本延迟、新证据和验证器稳定性，输出继续、回退、报告未知或人工升级。净收益依次为 31、4、−4 时第三轮不应默认执行；连续无新证据、补丁来回、验收冲突或预算耗尽都触发停止。轮数更多不代表修正更可靠。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>怎样证明反思优于多采样<span class=\"dd-badge eng\">评测</span></h2><p class=\"dd-lead\">多调用一次模型本身就可能提高命中率，如何隔离“反馈”的贡献？</p><p>在相同 token、模型调用和墙钟预算下比较：直接单次、无反馈再采样、带外部反馈反思、更强模型单次。除最终成功率外，报告首轮正确被改坏率、每轮边际收益、测试覆盖、平均轮数、回退率和人工升级率。若无反馈多采样同样有效，复杂反思框架没有证明必要性。</p><p>评测集应保留隐藏测试，防止反思器针对可见测试过拟合；同时包含“原答案正确”的对照案例，才能测出过度修改。</p><p>反思评测输入同预算的直接单次、无反馈多采样、外部反馈反思和更强模型单次，输出最终成功、首轮正确改坏率、边际收益、轮数、回退和升级。隐藏测试防止针对可见验收过拟合，原答案正确的对照样本测过度修改。若无反馈多采样同样有效，就没有证明复杂反思框架的必要性。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与路线</span></h2><p class=\"dd-lead\">反思是受证据约束的控制过程，不是人格化的自省能力。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody><tr><td>模型会知道自己哪里错</td><td>自评可能共享原盲点，需外部证据约束</td></tr><tr><td>批评越详细越可靠</td><td>关键是定位到可证伪原因和单一动作</td></tr><tr><td>测试通过即可存成通用经验</td><td>经验必须绑定适用条件、版本和反例</td></tr><tr><td>反思轮数越多越好</td><td>边际收益会下降，改坏率、成本与延迟会上升</td></tr><tr><td>修改测试也属于修复</td><td>验收默认受保护，除非独立需求证据证明测试错误</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>Agent 循环、ReAct、评测、代码执行</td></tr><tr><td><b>本页核心</b></td><td>失败证据、原因假设、最小补丁、回归验证和停止条件</td></tr><tr><td>紧邻</td><td>自一致性、规划、人在回路、Agent 记忆</td></tr><tr><td>工程延伸</td><td>可观测性、奖励投机、测试时计算和数据治理</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义受保护验收</li><li>运行候选并采集外部失败</li><li>把证据压成原因假设</li><li>应用单一可回退改动</li><li>复跑失败与保护性测试</li><li>按边际收益和无进展停止</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么“再想一遍”不等于反思？</li><li>有效反思记录的四个核心字段？</li><li>为何要保护原验收？</li><li>反思记忆为何要有适用条件？</li><li>如何证明收益来自反馈？</li><li>假设“反思与自我修正：让失败证据改变下一次行动”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>没有新证据时仍在同一信息与盲点内重采样。</li><li>失败证据、原因假设、单一改动、预期验证。</li><li>防止模型通过删测试或放宽断言伪造成功。</li><li>局部经验脱离前提会污染其他任务。</li><li>同预算比较无反馈多采样，并报告改坏率与边际收益。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2303.11366\" target=\"_blank\" rel=\"noopener\">Reflexion: Language Agents with Verbal Reinforcement Learning</a>：语言反馈式修正与经验记忆</li><li><a href=\"https://arxiv.org/abs/2303.17651\" target=\"_blank\" rel=\"noopener\">Self-Refine: Iterative Refinement with Self-Feedback</a>：生成—反馈—修正循环</li><li><a href=\"https://arxiv.org/abs/2305.11738\" target=\"_blank\" rel=\"noopener\">CRITIC: Large Language Models Can Self-Correct with Tool-Interactive Critiquing</a>：用外部工具反馈约束批评</li><li><a href=\"https://arxiv.org/abs/2310.01798\" target=\"_blank\" rel=\"noopener\">Large Language Models Cannot Self-Correct Reasoning Yet</a>：无外部反馈自纠的边界</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
